
   .:[ events : which signal notifies how ]:.

## read by events.notify.apply when a signal is raised [ no reload needed, ##
## the file is read again when it changes ]. `=` and `:` are equivalent,   ##
## backslash continues a line :                                            ##
##   notify.by.<signal> = <value key> ..   the values that pick an entry   ##
##   notify.on.<signal>[.<value>..] = level=info|warn|loves|none \         ##
##        sound=soft|aware|alert|none ticker=set|clear key=<line key> \    ##
##        text=<rest of the line, {value} filled in>                       ##
## claude states : ok failed ; kimi : end_turn .. error stopped crashed    ##
##   notify.same.<signal> = <value key> ..  what makes two cues the same   ##
##        [ default : the notify.by keys ] ; a repeat inside the window    ##
##        [ base.interval type notify-repeat ] is counted, not sent, and   ##
##        the count shown on the next one. the ticker is never limited     ##
## the most specific entry wins, then shorter ones ; no entry : nothing    ##
## sounds : bin/warning-sound -profile ; sound=alarm is reserved [ the     ##
## alarm loop is a later stage, played as alert until then ]               ##

## runs : the ticker line goes when the run is done ; a run.start signal ##
## sets it [ claude : each turn, kimi : each prompt ]                    ##
notify.on.claude.run.start      = level=none ticker=set text=claude running
notify.on.kimi.run.start        = level=none ticker=set text=kimi running

notify.by.claude.run.done       = state
notify.on.claude.run.done       = level=info sound=soft ticker=clear \
                                  text=claude run {state}
notify.on.claude.run.done.failed = level=warn sound=aware ticker=clear \
                                  text=claude run failed {reason}

notify.by.kimi.run.done         = state
notify.on.kimi.run.done         = level=info sound=soft ticker=clear \
                                  text=kimi run {state}
notify.on.kimi.run.done.failed  = level=warn sound=aware ticker=clear \
                                  text=kimi run failed
notify.on.kimi.run.done.error   = level=warn sound=aware ticker=clear \
                                  text=kimi run error
notify.on.kimi.run.done.crashed = level=warn sound=aware ticker=clear \
                                  text=kimi run crashed

## usage : thresholds going up at 75 and 90, nothing going down ##
notify.by.usage.threshold       = crossed percent
notify.same.usage.threshold     = provider window crossed percent
notify.same.usage.window.reset  = provider window
notify.on.usage.threshold       = level=none
notify.on.usage.threshold.up.75 = level=info sound=soft \
                                  text={provider} {window} at {used} %
notify.on.usage.threshold.up.90 = level=warn sound=aware \
                                  text={provider} {window} at {used} %
notify.on.usage.window.reset    = level=info sound=soft \
                                  text={provider} {window} window reset

## quiet hours [ local time ] : sounds become soft or none ##
notify.quiet.hours              = 23-7
notify.quiet.sound              = soft

